// Read once, to carry curbs picked under the old select-then-save flow into the default set, and then
// removed. Nothing writes it any more; see migrateLegacyCurrentSelection.
const CURRENT_SELECTION_KEY = "sloans-lake-current-selection";
const SAVED_SETS_KEY = "sloans-lake-notification-sets";
// Turning a curb's reminder on adds it here. The id is fixed rather than timestamped so that two
// devices signed in to one account each grow the same set instead of each minting a "My curbs" of
// their own, and mergeAccountLibrary can union them by id.
const DEFAULT_SET_ID = "set-my-curbs";
const DEFAULT_SET_NAME = "My curbs";
const NOTIFICATION_JOBS_KEY = "sloans-lake-notification-jobs";
const DELIVERED_JOBS_KEY = "sloans-lake-delivered-notification-jobs";
const PUSH_SUBSCRIPTION_KEY = "sloans-lake-push-subscription";
// Everything this client used to hardcode about Denver is one record in public/cities.js now:
// the map rectangle, the published inventory URL, the boundary module that draws the city line,
// and the address grid that turns a house number into a point. There is one city in the registry,
// so ACTIVE_CITY never moves today -- the point is that the second one is an entry over there
// rather than a search through this file for the word "Denver".
const ACTIVE_CITY = window.CityRegistry.getActiveCity();
const CITY_MAP_BOUNDS = ACTIVE_CITY.bounds;
const CITY_NAME_PATTERN = new RegExp(`\\b${ACTIVE_CITY.name}\\b`, "i");
const STATIC_ROUTE_INVENTORY_URL = ACTIVE_CITY.inventoryUrl;
const CITY_SWEEP_SEASON = ACTIVE_CITY.sweepSeason || null;
const ONBOARDING_DISMISSED_KEY = "denver-curb-alerts-onboarding-dismissed";
const PUSH_PRIMER_DISMISSED_KEY = "denver-curb-alerts-push-primer-dismissed";
const MOVED_SWEEPS_KEY = "denver-curb-alerts-moved-sweeps";
// Where the car is right now, as one pin. It is kept apart from the saved sets on purpose: those are
// the curbs someone parks on and sync to an account, while this is one car's position on one phone.
const PARKED_CAR_KEY = "denver-curb-alerts-parked-car";
// A phone's fix is good to 5-15 m between buildings, which is wider than the gap between the two
// curbs of a residential street. So the pin decides the street, and the side is offered rather than
// asserted: the nearest curb is the guess, and the one across the street is a tap away.
const PARKING_SEARCH_RADIUS_METRES = 40;
const PARKING_SIDE_OPPOSITES = { north: "south", south: "north", east: "west", west: "east" };
const memoryStore = new Map();
const DEFAULT_DAY_OF_REMINDERS = [
  { enabled: true, time: "07:00" },
  { enabled: false, time: "09:00" },
  { enabled: false, time: "11:00" }
];
const DEFAULT_REMINDERS = {
  dayBeforeEnabled: true,
  dayBeforeTime: "18:00",
  dayOfReminders: DEFAULT_DAY_OF_REMINDERS,
  nagUntilMoved: true
};
// One reminder is how people get the ticket anyway: an alert swiped away at 7am is forgotten by
// 7:05. With nagUntilMoved on, a sweep keeps reminding - a check-in later the night before, then
// follow-ups after the first sweep-day alert - until the driver taps "I moved my car". Denver
// publishes sweep dates but no start times, so the follow-ups hang off the driver's own first
// alert rather than off a sweep time the data does not have.
const EVENING_CHECK_IN_TIME = "21:00";
const SWEEP_DAY_FOLLOW_UP_MINUTES = [30, 60];
// Least to most urgent. A job that lands on two stages at once takes the copy of the later one.
const JOB_KIND_URGENCY = ["day-before", "evening-check", "day-of", "follow-up", "last-call"];

const colors = {
  north: "#2f9e44",
  south: "#e07a1f",
  east: "#d64545",
  west: "#2f6fed",
  unavailable: "#ff2d8d",
  notMaintained: "#7b8790",
  // Plum, for curbs Denver sweeps on a schedule you never have to move for. It was picked against
  // the other six rather than for taste: the obvious teal sits at a CIELAB deltaE of 1.0 from the
  // pink once deuteranopia is simulated, which would have made "you are fine here" and "we have no
  // data, be careful" the same colour for red-green colourblind users. Plum is the furthest from
  // all six in both normal vision (35.7) and simulated deuteranopia (31.3).
  noRelocation: "#8e44ad"
};

// Every curb colour is decided here so the live and embedded datasets cannot drift apart. Order
// matters: the three schedule states each override the north/south/east/west side colour, because
// what the curb *is* matters more to a parked driver than which side of the street it sits on.
function getCurbColor(schedule, sideColor) {
  if (schedule?.sweepType === "NotMaintained") {
    return colors.notMaintained;
  }
  if (!schedule || schedule.sweepType === "Unavailable") {
    return colors.unavailable;
  }
  if (schedule.relocationRequired === false) {
    return colors.noRelocation;
  }
  return sideColor;
}

