function parseSweepDate(dateString) {
  if (!dateString) {
    return null;
  }

  const [month, day, year] = dateString.split("/").map(Number);
  if (!month || !day || !year) {
    return null;
  }

  return new Date(year, month - 1, day, 0, 0, 0, 0);
}

function addDays(date, count) {
  const nextDate = new Date(date);
  nextDate.setDate(nextDate.getDate() + count);
  return nextDate;
}

function viewFromHash() {
  const hashValue = window.location.hash.replace("#", "").trim();
  return APP_VIEW_NAMES.has(hashValue) ? hashValue : "";
}

function setActiveView(viewName, options = {}) {
  // The scheduled-alerts page folded into the alerts page; old hashes still resolve.
  if (viewName === "schedule") {
    viewName = "alerts";
  }

  if (!APP_VIEW_NAMES.has(viewName)) {
    return;
  }

  appViews.forEach((view) => {
    const isActive = view.dataset.view === viewName;
    view.hidden = !isActive;
    view.classList.toggle("is-active", isActive);
  });

  appViewButtons.forEach((button) => {
    const isActive = button.dataset.viewTarget === viewName;
    button.classList.toggle("is-active", isActive);

    if (button.classList.contains("app-tab")) {
      if (isActive) {
        button.setAttribute("aria-current", "page");
      } else {
        button.removeAttribute("aria-current");
      }
    }
  });

  if (!options.skipHash) {
    window.history.replaceState(null, "", `#${viewName}`);
  }

  if (viewName === "setup" && state.map) {
    // Resizing the map changes which curbs the viewport covers, and invalidateSize does not fire
    // moveend, so the cull has to be told to run again.
    window.setTimeout(() => {
      state.map.invalidateSize();
      scheduleMapRender();
    }, 80);
  }

  if (!options.skipScroll) {
    window.scrollTo({ top: 0, behavior: options.instant ? "auto" : "smooth" });
  }
}

function initializeViewNavigation() {
  appViewButtons.forEach((button) => {
    button.addEventListener("click", () => {
      setActiveView(button.dataset.viewTarget);
    });
  });

  window.addEventListener("hashchange", () => {
    const nextView = viewFromHash();
    if (nextView) {
      setActiveView(nextView, { skipHash: true });
    }
  });

  setActiveView(viewFromHash() || "setup", { skipHash: true, instant: true });
}

function applyTimeToDate(baseDate, timeValue) {
  if (!baseDate || !isValidTimeValue(timeValue)) {
    return null;
  }

  const [hourText, minuteText] = timeValue.split(":");
  return new Date(
    baseDate.getFullYear(),
    baseDate.getMonth(),
    baseDate.getDate(),
    Number(hourText),
    Number(minuteText),
    0,
    0
  );
}

function registerEvents() {
  registerAccountEvents();
  useMyLocationButton?.addEventListener("click", requestUserLocation);
  curbSheetClose?.addEventListener("click", closeCurbSheet);
  parkHereButton?.addEventListener("click", parkHere);
  curbSheetPark?.addEventListener("click", () => {
    const segment = activeCurbSheetSegmentId ? getSegmentById(activeCurbSheetSegmentId) : null;
    if (!segment) {
      return;
    }
    if (curbSheetPark.dataset.parkedHere === "true") {
      openParkSheet();
      return;
    }
    const point = activeCurbSheetLatLng || { lat: getGeometryMidpoint(segment.geometry)[0], lon: getGeometryMidpoint(segment.geometry)[1] };
    parkCarAt(point.lat, point.lon, { segmentId: segment.id });
  });
  parkSheetClose?.addEventListener("click", closeParkSheet);
  parkSheetDone?.addEventListener("click", closeParkSheet);
  parkSheetClear?.addEventListener("click", clearParkedCar);
  parkSheetSideAcross?.addEventListener("click", () => {
    const pin = state.parkedCar?.pin;
    if (pin && parkSheetSideAcross.dataset.segmentId) {
      parkCarAt(pin.lat, pin.lon, { segmentId: parkSheetSideAcross.dataset.segmentId, adjusting: true });
    }
  });
  pushPrimerAccept?.addEventListener("click", acceptPushPrimer);
  pushPrimerDismiss?.addEventListener("click", dismissPushPrimer);
  installHelpButton?.addEventListener("click", openInstallSheet);
  installSheetClose?.addEventListener("click", closeInstallSheet);
  installSheetDone?.addEventListener("click", closeInstallSheet);
  curbSheetAction?.addEventListener("click", () => {
    if (activeCurbSheetSegmentId) {
      toggleCurbReminder(activeCurbSheetSegmentId);
    }
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") {
      return;
    }
    if (installSheet && !installSheet.hidden) {
      closeInstallSheet();
      return;
    }
    if (activeCurbSheetSegmentId) {
      closeCurbSheet();
      return;
    }
    if (state.parkSheetOpen) {
      closeParkSheet();
    }
  });
  onboardingDismissButton?.addEventListener("click", dismissOnboarding);
  curbSheetUndo?.addEventListener("click", undoCurbReminderChange);
  enableNotificationsButton.addEventListener("click", requestBrowserNotifications);
  sendTestButton.addEventListener("click", sendImmediateTestNotification);
  scheduleTestButton.addEventListener("click", scheduleHostedTestNotification);
  issueReportForm?.addEventListener("submit", submitIssueReport);
  openIssueReportButton?.addEventListener("click", toggleIssueReportPanel);
  closeIssueReportButton?.addEventListener("click", () => setIssueReportPanelOpen(false));
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      setIssueReportPanelOpen(false);
    }
  });
  lookupForm?.addEventListener("submit", (event) => {
    event.preventDefault();
    searchAddressAndCenter(lookupAddressInput?.value);
  });
  returnToPilotButton?.addEventListener("click", () => {
    loadSloansLakeFullInventory();
  });
  neighborhoodPresetButtons.forEach((button) => {
    button.addEventListener("click", () => {
      const address = button.dataset.address || "";
      const label = button.dataset.label || "Live Denver lookup";
      loadDenverLookup(address, label);
    });
  });
  if (!lookupForm) {
    lookupAddressButton?.addEventListener("click", () => {
      searchAddressAndCenter(lookupAddressInput?.value);
    });
    lookupAddressInput?.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        searchAddressAndCenter(lookupAddressInput.value);
      }
    });
  }
}

